{"version":3,"file":"PortalHeader.jsdbx","sources":["../../src/client/components/PortalHeader.tsx"],"sourcesContent":["import React from "react";

interface PortalHeaderProps {
  currentView: string;
  navigateToView: (view: string, id?: string | null, opts?: { title?: string }) => void;
}

export default function PortalHeader({ currentView, navigateToView }: PortalHeaderProps) {
  return (
    <header className="portal-header">
      <div className="portal-header__brand">
        <div className="portal-header__logo">
          <svg viewBox="0 0 24 24" className="portal-header__icon" aria-hidden="true">
            <path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </div>
        <div className="portal-header__titles">
          <h1 className="portal-header__title">VoltWorks Plant Access</h1>
          <span className="portal-header__subtitle">Visitor Request Portal</span>
        </div>
      </div>
      <nav className="portal-header__nav">
        <a
          href="?view=home"
          className={`nav-btn ${currentView === "home" ? "nav-btn--active" : ""}`}
          onClick={(e) => { e.preventDefault(); navigateToView("home", null, { title: "VoltWorks Plant Access Portal" }); }}
        >
          Home
        </a>
        <a
          href="?view=create"
          className={`nav-btn nav-btn--primary ${currentView === "create" ? "nav-btn--active" : ""}`}
          onClick={(e) => { e.preventDefault(); navigateToView("create", null, { title: "New Access Request" }); }}
        >
          New Request
        </a>
        <a
          href="?view=requests"
          className={`nav-btn ${currentView === "requests" ? "nav-btn--active" : ""}`}
          onClick={(e) => { e.preventDefault(); navigateToView("requests", null, { title: "My Access Requests" }); }}
        >
          My Requests
        </a>
      </nav>
    </header>
  );
}
